import itertools
from collections import Counter


def _routes(data, exact, minimum_duration):
    required = data.get("required", [])
    required_bits = {node: 1 << i for i, node in enumerate(required)}
    full_mask = (1 << len(required)) - 1
    source, target = data["source"], data["target"]
    start, deadline = data["start"], data["deadline"]
    budget = data["coupons"]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    initial_mask = required_bits.get(source, 0)
    initial = (source, initial_mask, 0)
    best = {initial: start}
    queue = [(start, source, initial_mask, 0)]
    while queue:
        time, node, mask, spent = heapq.heappop(queue)
        state = (node, mask, spent)
        if best.get(state) != time:
            continue
        if (node == target and mask == full_mask and
                (not exact or spent == budget)):
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            destination = edge["v"]
            next_mask = mask | required_bits.get(destination, 0)
            durations = [(edge["duration"], spent)]
            if spent < budget:
                discounted = max(minimum_duration,
                                 edge["duration"] - edge.get("discount", 0))
                durations.append((discounted, spent + 1))
            for duration, next_spent in durations:
                arrival = depart + duration
                if arrival > deadline:
                    continue
                next_state = (destination, next_mask, next_spent)
                if arrival < best.get(next_state, float("inf")):
                    best[next_state] = arrival
                    heapq.heappush(queue, (arrival, destination, next_mask,
                                           next_spent))
    return {"arrival": None}


def _route_solver(exact, minimum_duration):
    return lambda data: _routes(data, exact, minimum_duration)


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    half_up = data["rounding"] == "half_up"

    def rounded(numerator):
        if half_up:
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    rows_by_version = {
        name: {row["version"]: row for row in packages[name]}
        for name in names
    }
    choices = [[None] + list(rows_by_version[name]) for name in names]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    features = set(data.get("features", []))
    best_vector = None
    best_install = None

    for values in itertools.product(*choices):
        install = {name: version for name, version in zip(names, values)
                   if version is not None}
        if any(name not in install or not low <= install[name] <= high
               for name, (low, high) in roots.items()):
            continue
        if any(version in blocked.get(name, [])
               for name, version in install.items()):
            continue
        if any(name in install and install[name] != version
               for name, version in pins.items()):
            continue

        graph = {name: [] for name in install}
        reachable = set()
        pending = list(roots)
        valid = True
        while pending and valid:
            name = pending.pop()
            if name in reachable:
                continue
            if name not in install:
                valid = False
                break
            reachable.add(name)
            row = rows_by_version[name][install[name]]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                version = install.get(other)
                if version is None or not dep["min"] <= version <= dep["max"]:
                    valid = False
                    break
                graph[name].append(other)
                pending.append(other)
        if not valid or reachable != set(install):
            continue

        finished, active = set(), set()

        def acyclic(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not acyclic(other) for other in graph[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(acyclic(name) for name in graph):
            continue
        vector = tuple(install.get(name, -1) for name in names)
        if best_vector is None or vector > best_vector:
            best_vector, best_install = vector, install

    if best_install is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_install}


def _intervals(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    options = [job for job in jobs if job["id"] not in blocked]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    best_value = None
    best_ids = None

    for selected in itertools.combinations(options, k):
        ids = {job["id"] for job in selected}
        if not mandatory.issubset(ids):
            continue
        counts = Counter(job["group"] for job in selected)
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        active_ends = []
        valid = True
        for job in sorted(selected, key=lambda item: (item["start"], item["end"])):
            active_ends = [end for end in active_ends if end > job["start"]]
            active_ends.append(job["end"])
            if len(active_ends) > 2:
                valid = False
                break
        if not valid:
            continue
        value = sum(job["value"] for job in selected)
        sorted_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids < best_ids)):
            best_value, best_ids = value, sorted_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


